insert into public.commands (nr, title, short, description, template, fields, measures, sort_order)
values
  ('1', 'Vorbeifahrt am EOA / am Signal', 'Vorbeifahrt am Signal', 'Genehmigung, an einem Halt zeigenden oder gestörten Signal bzw. an einem EOA vorbeizufahren.', '110 darf am Halt zeigenden / gestörten Signal (111) in (112) vorbeifahren. 113 darf zusätzlich an allen Signalen bis (114) vorbeifahren.', $befehl$[{"id":"signal","label":"111 Signal / EOA","options":["Esig 60A","Esig 70A","Esig 80A","Esig 90A","ASig 62B","ASig 72B","ASig 82B","ASig 92B","Bksig 48","EOA 12,4","Signal Ne 1"],"placeholder":"Signal wählen"},{"id":"stelle","label":"112 Zugmeldestelle","options":["Musterstadt","Talheim","Nordheim","Südheim"],"placeholder":"Zugmeldestelle wählen"},{"id":"bis","label":"114 bis Signal","options":["Esig 60A","Esig 70A","Esig 80A","Esig 90A","ASig 62B","ASig 72B","ASig 82B","ASig 92B","Bksig 48","EOA 12,4","Signal Ne 1"],"placeholder":"Signal wählen"}]$befehl$::jsonb, $befehl$[{"id":"sicht","label":"×25 – ist vom Fahren auf Sicht befreit"}]$befehl$::jsonb, 0),
  ('2', 'Weiterfahren nach TR / nach Vorbeifahrt', 'Weiterfahren nach TR', 'Weiterfahrt nach einer ETCS-Zwangsbremsung (TR) oder nach einer Vorbeifahrt an einer Halt gebietenden Stelle.', '2.10 darf in SR weiterfahren, wenn keine ETCS-Fahrterlaubnis empfangen wurde. ×25 ist vom Fahren auf Sicht befreit.', $befehl$[{"id":"mode","label":"Weiterfahren nach","options":["TR – Zwangsbremsung","Vorbeifahrt am Signal"],"placeholder":"Anlass wählen"}]$befehl$::jsonb, $befehl$[{"id":"sr","label":"in SR weiterfahren, wenn keine ETCS-Fahrterlaubnis empfangen wurde"},{"id":"sicht","label":"×25 – ist vom Fahren auf Sicht befreit"}]$befehl$::jsonb, 1),
  ('3', 'Verbleiben im Stillstand', 'Verbleiben im Stillstand', 'Der Zug muss an der aktuellen Stelle stehen bleiben; vorhandene ETCS-Fahrterlaubnis wird gelöscht.', '3.10 Verbleiben im Stillstand. 3.15 „Fahrt beenden“ durchführen. 3.20 Vorhandene ETCS-Fahrterlaubnis löschen.', $befehl$[{"id":"ort","label":"Standort","options":["Musterstadt","Talheim","Nordheim","Südheim"],"placeholder":"Standort wählen"}]$befehl$::jsonb, $befehl$[{"id":"fahrtBeenden","label":"„Fahrt beenden“ durchführen"},{"id":"maLoeschen","label":"Vorhandene ETCS-Fahrterlaubnis löschen"}]$befehl$::jsonb, 2),
  ('5', 'Fahren mit Geschwindigkeitsbegrenzung', 'Geschwindigkeitsbegrenzung', 'Fahrt mit einer angeordneten Höchstgeschwindigkeit zwischen zwei Signalen bzw. Zugmeldestellen.', 'x.41 Geschwindigkeitsbegrenzung x.42 km/h zwischen/in x.47 von x.43 bis x.48 – Grund x.96.', $befehl$[{"id":"speed","label":"x.42 Höchstgeschwindigkeit","options":["20 km/h","30 km/h","40 km/h","50 km/h","60 km/h","80 km/h","100 km/h"],"placeholder":"km/h wählen"},{"id":"von","label":"x.47 Von (Signal)","options":["Esig 60A","Esig 70A","Esig 80A","Esig 90A","ASig 62B","ASig 72B","ASig 82B","ASig 92B","Bksig 48","EOA 12,4","Signal Ne 1"],"placeholder":"Signal wählen"},{"id":"bis","label":"x.48 Bis (Signal)","options":["Esig 60A","Esig 70A","Esig 80A","Esig 90A","ASig 62B","ASig 72B","ASig 82B","ASig 92B","Bksig 48","EOA 12,4","Signal Ne 1"],"placeholder":"Signal wählen"},{"id":"grund","label":"x.96 Grund","options":["10 – Gleis kann besetzt sein","11 – Personen im Gleis","17 – Auf der Strecke ruht die Arbeit","19 – Bahnübergang nicht ausreichend gesichert","22 – Bauarbeiten","23 – Unbefahrbare Stelle im gesperrten Gleis","25 – Arbeitsstelle nicht benachrichtigt","26 – Niedrigere Geschwindigkeit gegenüber La","29 – Mängel am Oberbau","30 – Verdacht auf Oberleitungsschäden","31 – Verdacht auf Unwetterschäden","33 – PZB-Streckeneinrichtung gestört","34 – Weichen außer Abhängigkeit"],"placeholder":"Grund wählen"}]$befehl$::jsonb, $befehl$[]$befehl$::jsonb, 3),
  ('6', 'Fahren nach Sicht', 'Fahren nach Sicht', 'Der Triebfahrzeugführer muss den folgenden Abschnitt auf Sicht befahren und die Strecke prüfen.', '6.40 Fahren auf Sicht von x.47 bis x.48. x.90 Strecke aus folgendem Grund prüfen: x.91.', $befehl$[{"id":"von","label":"x.47 Von (Signal)","options":["Esig 60A","Esig 70A","Esig 80A","Esig 90A","ASig 62B","ASig 72B","ASig 82B","ASig 92B","Bksig 48","EOA 12,4","Signal Ne 1"],"placeholder":"Signal wählen"},{"id":"bis","label":"x.48 Bis (Signal)","options":["Esig 60A","Esig 70A","Esig 80A","Esig 90A","ASig 62B","ASig 72B","ASig 82B","ASig 92B","Bksig 48","EOA 12,4","Signal Ne 1"],"placeholder":"Signal wählen"},{"id":"grund","label":"x.91 Grund","options":["10 – Gleis kann besetzt sein","11 – Personen im Gleis","17 – Auf der Strecke ruht die Arbeit","19 – Bahnübergang nicht ausreichend gesichert","22 – Bauarbeiten","23 – Unbefahrbare Stelle im gesperrten Gleis","25 – Arbeitsstelle nicht benachrichtigt","26 – Niedrigere Geschwindigkeit gegenüber La","29 – Mängel am Oberbau","30 – Verdacht auf Oberleitungsschäden","31 – Verdacht auf Unwetterschäden","33 – PZB-Streckeneinrichtung gestört","34 – Weichen außer Abhängigkeit"],"placeholder":"Grund wählen"}]$befehl$::jsonb, $befehl$[]$befehl$::jsonb, 4),
  ('7', 'Start in SR', 'Start in SR', 'Genehmigung, nach dem Vorbereiten einer Fahrt in der ETCS-Betriebsart SR zu starten.', '7.10 darf in SR starten. 7.20 darf vorbeifahren am EOA / Signal (7.21). ×25 ist vom Fahren auf Sicht befreit.', $befehl$[{"id":"eoa","label":"7.21 Signal / EOA","options":["Esig 60A","Esig 70A","Esig 80A","Esig 90A","ASig 62B","ASig 72B","ASig 82B","ASig 92B","Bksig 48","EOA 12,4","Signal Ne 1"],"placeholder":"Signal / EOA wählen"}]$befehl$::jsonb, $befehl$[{"id":"sicht","label":"×25 – ist vom Fahren auf Sicht befreit"}]$befehl$::jsonb, 5),
  ('8', 'BÜ sichern', 'BÜ sichern', 'Anweisung, einen Bahnübergang zu sichern und gegebenenfalls davor zu halten.', '8.40 Information über einen oder mehrere defekte Bahnübergänge. 8.50 muss halten vor BÜ und darf weiterfahren, wenn BÜ gesichert ist.', $befehl$[{"id":"bue","label":"8.51 Bahnübergang","options":["BÜ km 8,7","BÜ km 12,4","BÜ km 15,1","BÜ km 21,6"],"placeholder":"Bahnübergang wählen"},{"id":"speed","label":"x.42 Höchstgeschwindigkeit","options":["20 km/h","30 km/h","40 km/h","50 km/h","60 km/h","80 km/h","100 km/h"],"placeholder":"km/h wählen"}]$befehl$::jsonb, $befehl$[{"id":"sichern","label":"8.50 – halten vor BÜ und weiterfahren, wenn BÜ gesichert ist"}]$befehl$::jsonb, 6),
  ('9', 'Fahren mit eingeschränkter Fahrstromversorgung', 'Eingeschränkter Fahrstrom', 'Fahrt in einem Abschnitt mit eingeschränkter Fahrstromversorgung, z. B. mit gesenktem Stromabnehmer.', '9.40 Eingeschränkte Fahrstromversorgung zwischen x.47 und x.48. 9.70 Fahren mit gesenktem Stromabnehmer.', $befehl$[{"id":"von","label":"x.47 Von (Signal)","options":["Esig 60A","Esig 70A","Esig 80A","Esig 90A","ASig 62B","ASig 72B","ASig 82B","ASig 92B","Bksig 48","EOA 12,4","Signal Ne 1"],"placeholder":"Signal wählen"},{"id":"bis","label":"x.48 Bis (Signal)","options":["Esig 60A","Esig 70A","Esig 80A","Esig 90A","ASig 62B","ASig 72B","ASig 82B","ASig 92B","Bksig 48","EOA 12,4","Signal Ne 1"],"placeholder":"Signal wählen"}]$befehl$::jsonb, $befehl$[{"id":"pantograph","label":"9.70 – Fahren mit gesenktem Stromabnehmer"},{"id":"hauptschalter","label":"9.75 – Fahren mit ausgeschaltetem Hauptschalter"}]$befehl$::jsonb, 7),
  ('21', 'Einfahrt / Weiterfahrt', 'Einfahrt / Weiterfahrt', 'Einfahrt in einen Bahnhof, Bahnhofsteil, Abzweig oder eine Überleitstelle bzw. Weiterfahrt dort.', '21.10 darf in/auf der 21.11 einfahren / weiterfahren.', $befehl$[{"id":"stelle","label":"21.11 Zugmeldestelle","options":["Musterstadt","Talheim","Nordheim","Südheim"],"placeholder":"Zugmeldestelle wählen"},{"id":"gleis","label":"21.12 Gleis","options":["Gleis 1","Gleis 2","Gleis 3"],"placeholder":"Gleis wählen"},{"id":"art","label":"21.13 Fahrt","options":["einfahren","weiterfahren"],"placeholder":"Art wählen"}]$befehl$::jsonb, $befehl$[]$befehl$::jsonb, 8),
  ('22', 'Ausfahrt aus dem Bf / Bft', 'Ausfahrt aus dem Bf / Bft', 'Genehmigung zur Ausfahrt aus einem Bahnhof oder Bahnhofsteil, wenn kein Hauptsignal die Ausfahrt zulässt.', '22.10 darf aus dem 22.11 Bf / 22.12 Bft ausfahren.', $befehl$[{"id":"bf","label":"22.11 Bf / Bft","options":["Bft Musterstadt Nord","Bft Talheim Süd","Bft Nordheim West","Bft Südheim Ost","Bf Musterstadt","Bf Talheim","Bf Nordheim","Bf Südheim"],"placeholder":"Bahnhof / Bahnhofsteil wählen"},{"id":"richtung","label":"Ausfahrt Richtung","options":["Richtung Musterstadt","Richtung Talheim","Richtung Nordheim","Richtung Südheim"],"placeholder":"Richtung wählen"}]$befehl$::jsonb, $befehl$[]$befehl$::jsonb, 9),
  ('23', 'Fahren auf dem Gegengleis', 'Fahren auf dem Gegengleis', 'Genehmigung, einen Streckenabschnitt auf dem Gegengleis zu befahren.', '23.10 fährt auf dem Gegengleis von 23.11 bis 23.12.', $befehl$[{"id":"von","label":"23.11 Von (Zugmeldestelle)","options":["Musterstadt","Talheim","Nordheim","Südheim"],"placeholder":"Zugmeldestelle wählen"},{"id":"bis","label":"23.12 Bis (Zugmeldestelle)","options":["Musterstadt","Talheim","Nordheim","Südheim"],"placeholder":"Zugmeldestelle wählen"}]$befehl$::jsonb, $befehl$[]$befehl$::jsonb, 10),
  ('24', 'Rückfahrende Fahrten', 'Rückfahrende Fahrten', 'Anweisung für Sperrfahrten oder nicht gekuppelte Schiebetriebfahrzeuge, die zurückkehren.', '24.11 fährt / schiebt nach 24.12 und kehrt zurück 24.15 / 24.16.', $befehl$[{"id":"stelle","label":"24.12 Zugmeldestelle","options":["Musterstadt","Talheim","Nordheim","Südheim"],"placeholder":"Zugmeldestelle wählen"},{"id":"km","label":"24.15 km","options":["km 8,7","km 12,4","km 15,1","km 21,6","km 27,3"],"placeholder":"km wählen"}]$befehl$::jsonb, $befehl$[]$befehl$::jsonb, 11),
  ('25', 'Weiterfahren sowie Ein- und Ausfahren vom Gegengleis', 'Weiterfahren vom Gegengleis', 'Weiterfahrt vom Gegengleis bzw. Ein- und Ausfahrt in einen Bahnhof vom Gegengleis.', '25.30 darf vom Gegengleis ab 25.31 km in den 25.32 Bf / 25.33 Bft ein- und ausfahren.', $befehl$[{"id":"ab","label":"25.31 ab km","options":["km 8,7","km 12,4","km 15,1","km 21,6","km 27,3"],"placeholder":"km wählen"},{"id":"ziel","label":"25.32 Bf / 25.33 Bft","options":["Bft Musterstadt Nord","Bft Talheim Süd","Bft Nordheim West","Bft Südheim Ost"],"placeholder":"Ziel wählen"}]$befehl$::jsonb, $befehl$[]$befehl$::jsonb, 12),
  ('26', 'Halten auf dem Gegengleis', 'Halten auf dem Gegengleis', 'Der Zug muss auf dem Gegengleis vor einem Signal Ne 1 oder in Höhe eines Signals halten.', '26.10 muss auf dem Gegengleis halten vor Signal Ne 1 / in Höhe des 26.13 Signals.', $befehl$[{"id":"ort","label":"Halteort","options":["vor Signal Ne 1","in Höhe des Esig 70A","in Höhe des ASig 62B"],"placeholder":"Halteort wählen"},{"id":"km","label":"26.14 km","options":["km 8,7","km 12,4","km 15,1","km 21,6","km 27,3"],"placeholder":"km wählen"}]$befehl$::jsonb, $befehl$[]$befehl$::jsonb, 13),
  ('27', 'LZB abschalten', 'LZB abschalten', 'Anweisung, die LZB in einem bestimmten Abschnitt abzuschalten.', '27.10 muss die LZB von 27.11 bis 27.12 abschalten.', $befehl$[{"id":"von","label":"27.11 Von (Zugmeldestelle)","options":["Musterstadt","Talheim","Nordheim","Südheim"],"placeholder":"Zugmeldestelle wählen"},{"id":"bis","label":"27.12 Bis (Zugmeldestelle)","options":["Musterstadt","Talheim","Nordheim","Südheim"],"placeholder":"Zugmeldestelle wählen"}]$befehl$::jsonb, $befehl$[]$befehl$::jsonb, 14),
  ('28', 'ETCS-Stufe / ETCS-Betriebsmodus wechseln', 'ETCS-Stufe wechseln', 'Anweisung, einen bestimmten ETCS-Level bzw. eine bestimmte ETCS-Betriebsart zu wählen.', '28.10 muss ETCS-Level 28.11 wählen. 28.20 muss ETCS-Betriebsart 28.21 wählen.', $befehl$[{"id":"level","label":"28.11 ETCS-Level","options":["ETCS Level 1","ETCS Level 2","ETCS Level 3"],"placeholder":"Level wählen"},{"id":"mode","label":"28.21 ETCS-Betriebsart","options":["Betriebsart SR","Betriebsart OS","Betriebsart FS","Betriebsart TR"],"placeholder":"Betriebsart wählen"}]$befehl$::jsonb, $befehl$[]$befehl$::jsonb, 15)
